import{_ as d,o as e,c as a,ag as s}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovLSearch 直线寻位","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovLSearch.md","filePath":"3. 指令/1. 运动指令/MovLSearch.md","lastUpdated":1778862643000}'),r={name:"3. 指令/1. 运动指令/MovLSearch.md"};function i(o,t,n,h,l,c){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="movlsearch-直线寻位" tabindex="-1">MovLSearch 直线寻位 <a class="header-anchor" href="#movlsearch-直线寻位" aria-label="Permalink to &quot;MovLSearch 直线寻位&quot;">​</a></h1><p>寻位指令（MovLSearch）是指在执行该直线运动指令的过程中，实时进行 <strong>IO 信号检测</strong>或<strong>轴力矩检测</strong>。一旦满足设定的触发条件（如 IO 到达触发值或轴力矩达到阈值），机器人将停止当前指令的运行，记录位置并继续执行后续程序。</p><p><strong>注意：该指令会打断路径的过渡效果。</strong></p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovLSearch(P, [V], [B], [C], [Tool], [Coord], [PayLoad], Type, Number, Value, [StopType], [StopDecScale], R, [SearchP], [Goto], [DO])</p><p>MovLSearch(目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 搜索类型, 端口号, 触发值, [停止方式], [减速比例], 结果变量, [搜索点记录], [跳转行号], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的理论目标点位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定直线运动速度。SPEED 变量中的 <code>tcp</code>（平移）和 <code>ori</code>（旋转）分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / DEFAULT）</td><td>机器人逼近终点时的过渡方式。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / EXTTCP 变量 / 变位机变量</td><td>机器人执行该轨迹时使用的坐标系参数。</td><td>可选，默认使用当前系统设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的负载参数。</td><td>可选，默认使用当前系统设置的负载参数</td></tr><tr><td>Type</td><td>enum</td><td>检测类型：<br><code>DITrig</code>：物理数字输入口触发。<br><code>AITrig</code>：物理模拟量输入口触发。<br><code>SIMDITrig</code>：虚拟数字输入口触发。<br><code>SIMAITrig</code>：虚拟模拟量输入口触发。<br><code>TorqTrig</code>：力矩触发。</td><td>必填</td></tr><tr><td>Number</td><td>int</td><td>若为 <code>DITrig</code>，对应<strong>输入口号</strong>；若为 <code>TorqTrig</code>，对应<strong>轴编号</strong>。</td><td>必填</td></tr><tr><td>Value</td><td>real</td><td>检测阈值。若为 <code>DITrig</code>，为<strong>高低电平状态</strong>；若为 <code>TorqTrig</code>，为<strong>轴额定转矩的千分比</strong>。</td><td>必填</td></tr><tr><td>[StopType]</td><td>enum</td><td><code>HARDSTOP</code>（立即停止，默认）、<code>SOFTSTOP</code>（减速停止）、<code>DEFAULT</code>。</td><td>可选，默认 HARDSTOP</td></tr><tr><td>[StopDecScale]</td><td>real</td><td>仅在 <code>SOFTSTOP</code> 时有效，值越大减速越快。</td><td>可选</td></tr><tr><td>R</td><td>INT 变量</td><td>返回值：<code>0</code>（未满足条件结束）、<code>1</code>（运行中满足条件触发）、<code>2</code>（起点处已满足条件）。</td><td>必填</td></tr><tr><td>[SearchP]</td><td>CPOS</td><td>记录满足触发条件时刻的坐标位置。</td><td>可选</td></tr><tr><td>[Goto]</td><td>label</td><td>若寻位失败（R=0），程序跳转到该标签处。</td><td>可选</td></tr><tr><td>[DO]</td><td>string</td><td>指令结束后可触发的 IO 指令（如 <code>SetDO</code> 等）。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：直线寻位</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovLSearch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P2, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DITrig&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT0)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P3, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol><li>机器人以 50 速度直线运动到 P1 点。</li><li>随后向 P2 做直线运动，并实时监控 <strong>16 号输入口</strong>。</li><li>如果检测到<strong>高电平 (1)</strong>：机器人立即停止向 P2 的运动，将 <code>INT0</code> 设为 1，直接开始向 P3 运动。</li><li>如果运动到 P2 仍无信号：机器人到达 P2 后将 <code>INT0</code> 设为 0，继续向 P3 运动。</li></ol>`,15)])])}const E=d(r,[["render",i]]);export{k as __pageData,E as default};
